import json, re, datetime
try:
    def obj(x, default):
        if isinstance(x, type(default)): return x
        try: return json.loads(str(x))
        except Exception: return default
    def norm(x):
        return str(x or '').replace('İ','i').replace('I','ı').lower().strip()
    ones=['sıfır','bir','iki','üç','dört','beş','altı','yedi','sekiz','dokuz']
    tens=['','on','yirmi','otuz','kırk','elli','altmış','yetmiş','seksen','doksan']
    def num(n):
        n=int(n)
        if n<0: return 'eksi '+num(-n)
        if n<10: return ones[n]
        if n<100: return tens[n//10]+(' '+ones[n%10] if n%10 else '')
        if n<1000: return (ones[n//100]+' ' if n//100>1 else '')+'yüz'+(' '+num(n%100) if n%100 else '')
        for base,label in [(1000000000000,'trilyon'),(1000000000,'milyar'),(1000000,'milyon'),(1000,'bin')]:
            if n>=base: return ('' if base==1000 and n//base==1 else num(n//base)+' ')+label+(' '+num(n%base) if n%base else '')
        return ''
    def amount(v,cc='TL'):
        s=str(v)
        if 'e' in s.lower(): s=format(float(v),'.2f')
        a,_,b=s.partition('.')
        b=(b+'00')[:2]
        n=int(a); c=int(b)
        label={'TL':'Türk Lirası','USD':'Dolar','EUR':'Euro','GBP':'İngiliz Sterlini'}[cc]
        return num(n)+' '+label+(' '+num(c)+' '+('kuruş' if cc=='TL' else 'peni' if cc=='GBP' else 'sent') if c else '')
    months=['','Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık']
    def dt(s):
        try: return datetime.datetime.strptime(str(s),'%d.%m.%Y').date()
        except Exception: return None
    def dateword(s):
        d=dt(s)
        return str(d.day)+' '+months[d.month]+' '+str(d.year) if d else ''
    def digits(s): return ' '.join(ones[int(c)] for c in str(s) if c.isdigit())
    def safe_name(s):
        s=str(s or '').strip()
        if any(t in norm(s) for t in ['talimat','ignore','instructions','tam numara','önceki','system','prompt','şifre']): return ''
        return s
    def intro(c):
        name=safe_name(c.get('productName'))
        return 'Sonu '+digits(c.get('cardNumberLast4',''))+' ile biten '+(name+' ' if name else '')+'kartınız'
    def joinnames(xs): return xs[0] if len(xs)==1 else ', '.join(xs[:-1])+' ve '+xs[-1]
    def route(to, speech=None):
        vars['route']=to
        if speech is not None: vars['speech']=speech; vars['last_speech']=speech
    def ask(phase,speech,short=None):
        if vars.get('phase')!=phase:
            vars['q_tries']=0; vars['technical_tries']=0; vars['silences']=0
        vars['phase']=phase; vars['question']=speech; vars['short_question']=short or speech
        route('select' if phase=='select' else 'week_choice' if phase=='week_choice' else 'confirm' if phase in ['email_confirm','week_confirm','week_start','latest_confirm'] else 'outside' if phase=='outside' else 'reply',speech)
    def terminal(dest,speech):
        vars['phase']='closed'; route(dest,speech)
    def request(service):
        vars['phase']=service+'_wait'; vars['api_state']=''; vars['api_payload']='{}'; vars['api_code']=''; vars['read_tries']=int(vars.get('read_tries',0))+1
        route('api_'+service)
    def retry_question(prefix='',technical=False):
        key='technical_tries' if technical else 'q_tries'
        vars[key]=int(vars.get(key,0))+1
        if int(vars[key])>=3: terminal('menu_failed','Size şu anda yardımcı olamıyorum. Sizi ana menüye aktarıyorum.')
        else: route('select' if vars['phase']=='select' else 'week_choice' if vars['phase']=='week_choice' else 'confirm' if vars['phase'] in ['email_confirm','week_confirm','week_start','latest_confirm'] else 'outside' if vars['phase']=='outside' else 'reply',prefix+vars.get('short_question','Yanıtınızı tekrar söyler misiniz?'))
    def cards(): return obj(vars.get('cards'),[])
    def selected(): return obj(vars.get('selected'),{})
    def show_selection(prefix=''):
        cs=cards(); pool=obj(vars.get('pool'),list(range(len(cs))))
        names=[]
        for i in pool:
            c=cs[i]; name=safe_name(c.get('productName')) or 'sonu '+digits(c.get('cardNumberLast4',''))+' ile biten kart'
            if name not in names: names.append(name)
        vars['cards_public']='; '.join(names)
        stage=vars.get('select_stage','name')
        if stage=='four': q=(safe_name(cs[pool[0]].get('productName'))+' isimli birden fazla kartınız var. ' if safe_name(cs[pool[0]].get('productName')) else '')+'Kartınızın son dört hanesini söyler misiniz?'
        elif stage=='six': q='Son dört hanesi '+digits(cs[pool[0]].get('cardNumberLast4',''))+' olan birden fazla kartınız var. Kartınızın son altı hanesini söyler misiniz?'
        elif stage=='full': q='Son altı hanesi aynı olan birden fazla kartınız var. Kart numaranızı söyler misiniz?'
        else: q='Hangi kartınızın borcunu öğrenmek istersiniz?'+(' Örneğin, '+joinnames(names[:2])+' diyebilirsiniz.' if names else '')
        ask('select',prefix+q,'Kartınızı '+('son dört hanesiyle' if stage=='four' else 'son altı hanesiyle' if stage=='six' else 'numarasıyla' if stage=='full' else 'adıyla')+' belirtir misiniz?')
    def choose(i):
        c=cards()[i]
        if str(c.get('isMainCard')).lower()=='false':
            retry_question('Bu kart için ekstre borcu sorgulayamıyorum. Lütfen başka bir kart seçiniz. '); return
        vars['selected']=json.dumps(c,ensure_ascii=False); vars['card_number']=c['cardNumber']; vars['selected_index']=i
        vars['read_tries']=0; request('balance')
    def read_balance(b):
        today=datetime.datetime.fromisoformat(str(vars.get('now'))).date()
        close=dt(b.get('statementDate')); due=dt(b.get('lastPayDate')); nxt=dt(b.get('nextStatementDate'))
        currencies=[('TL','Türk Lirası'),('USD','Dolar'),('EUR','Euro'),('GBP','İngiliz Sterlini')]
        blocks=[(cc,name,b.get('debt'+cc)) for cc,name in currencies if isinstance(b.get('debt'+cc),dict) and b.get('debt'+cc)]
        clear=[name for cc,name,x in blocks if float(x.get('remainingDebt',0))<=0]
        has=any(float(x.get('remainingDebt',0))>0 for cc,name,x in blocks)
        no=b.get('statementPaymentStatus')=='NO_DEBT' or not has
        vars['no_statement']='yes' if no else 'no'
        head=intro(selected()); lines=[]
        only=vars.get('figure','all')
        if only=='due_only':
            lines.append(head+'. '+('Son ödeme tarihiniz bugündür.' if due==today else 'Son ödeme tarihiniz '+dateword(b.get('lastPayDate'))+'.' if due else 'Son ödeme tarihi bilgisi bulunmuyor.'))
        elif only=='min_only':
            lines.append(head+'.')
            for cc,name,x in blocks:
                if float(x.get('remainingDebt',0))>0: lines.append(name+' için ödenmesi gereken minimum tutar '+amount(x['minPayment'],cc)+'.')
            if no: lines.append('Ekstre borcunuz bulunmamaktadır.')
        elif not close:
            lines.append(head+' için henüz kesilmiş bir ekstre borcu bulunmamaktadır.')
            x=b.get('debtTL',{})
            if 'totalDebt' in x and float(x['totalDebt'])>=0: lines.append('Gelecek dönemler dahil toplam borcunuz '+amount(x['totalDebt'])+'.')
        elif close==today or nxt==today:
            lines.append(head+'. Hesap kesim tarihiniz bugün, ekstreniz saat sıfır itibarıyla kesilecek.')
            for cc,name,x in blocks:
                if float(x.get('totalDebt',0))>0: lines.append('Toplam '+name+' borcunuz '+amount(x['totalDebt'],cc)+'.')
            if all(float(x.get('totalDebt',0))<=0 for cc,name,x in blocks): lines.append('Toplam borcunuz bulunmamaktadır.')
        elif no:
            lines.append(head+'ın '+dateword(b['statementDate'])+' tarihli ekstresinden borcunuz bulunmamaktadır.')
            x=b.get('debtTL',{})
            if 'totalDebt' in x and float(x['totalDebt'])>=0: lines.append('Gelecek dönemler dahil toplam borcunuz '+amount(x['totalDebt'])+'.')
            if due: lines.append('Son ödeme tarihiniz '+('bugündür.' if due==today else dateword(b['lastPayDate'])+' olacaktır.'))
        elif due and today>due:
            lines.append(head+'. Son ödeme tarihiniz geçmiştir.')
            for cc,name,x in blocks:
                if float(x.get('totalDebt',0))>0: lines.append('Toplam '+name+' borcunuz '+amount(x['totalDebt'],cc)+'.')
            if clear: lines.append(joinnames(clear)+' borcunuz bulunmamaktadır.')
        else:
            opening=head+'a ait '+dateword(b['statementDate'])+' tarihinde kesilen ekstre '
            moved=[name for cc,name,x in blocks if cc!='TL' and float(x.get('transferAmount',0))>0]
            if moved: lines.append(joinnames(moved)+' cinsinden borcunuzun bir kısmı Türk Lirası borcunuza aktarılmıştır.')
            for cc,name,x in blocks:
                if float(x.get('remainingDebt',0))<=0: continue
                s=name+' borcunuz '+amount(x['statementDebt'],cc)
                if cc!='TL': s+=', kalan toplam borcunuz '+amount(x['remainingDebt'],cc)+', ödenmesi gereken minimum tutar '+amount(x['minPayment'],cc)+'.'
                elif float(x.get('remainingMinPayment',0))<=0: s+=', kalan toplam borcunuz '+amount(x['remainingDebt'])+'. Minimum ödemenizi yaptığınız için teşekkür ederiz.'
                elif float(x['remainingMinPayment'])>=float(x['minPayment']): s+=', ödenmesi gereken minimum tutar '+amount(x['minPayment'])+'.'
                else: s+=', ödenmesi gereken minimum tutar '+amount(x['minPayment'])+', kalan toplam borcunuz '+amount(x['remainingDebt'])+', kalan minimum ödeme tutarınız '+amount(x['remainingMinPayment'])+'.'
                lines.append(opening+s); opening=''
            if clear: lines.append(joinnames(clear)+' borcunuz bulunmamaktadır.')
        if due and today>due and b.get('automaticPaymentFlag')=='Y':
            a=b.get('debtTL',{}).get('remainAutomaticPaymentAmount',0)
            if float(a)>0: lines.append('Otomatik ödemenizden kalan tutar '+amount(a)+'.')
        if not no and only=='all' and due: lines.append('Borçlarınız için son ödeme tarihiniz '+('bugündür.' if due==today else dateword(b['lastPayDate'])+'.'))
        return ' '.join(lines)
    def after_read():
        pre=vars.get('reading',''); pending=vars.get('pending','none')
        if pending in ['email','earlier_email']:
            vars['action_prefix']=pre; vars['read_tries']=0; request('email'); return
        if pending=='week':
            vars['action_prefix']=pre; vars['read_tries']=0; request('week'); return
        seen=obj(vars.get('seen'),[]); i=int(vars['selected_index'])
        if i not in seen: seen.append(i)
        vars['seen']=json.dumps(seen)
        remaining=[j for j,c in enumerate(cards()) if j not in seen and str(c.get('isMainCard')).lower()!='false']
        if remaining and vars.get('figure','all')=='all':
            ask('another',pre+' Başka bir kartınızın borcunu öğrenmek ister misiniz?','Başka bir kartınızın borcunu öğrenmek ister misiniz?'); return
        if vars.get('no_statement')=='yes' and vars.get('figure','all')=='all': terminal('menu',pre+' Sizi ana menüye yönlendiriyorum.'); return
        vars['action_prefix']=pre; vars['read_tries']=0; request('email')
    def email_flow():
        prefix=vars.get('action_prefix',''); vars['action_prefix']=''
        available=bool(vars.get('email_address'))
        pending=vars.get('pending','none')
        if pending in ['email','earlier_email']:
            if not available:
                vars['pending']='none'
                ask('offer',prefix+' Bankamızda kayıtlı bir e-posta adresiniz bulunmadığı için ekstrenizi gönderemiyorum. Hesap kesim haftası değişikliği için uygunluğunuzu işlem sırasında kontrol edebiliriz. İster misiniz?','Hesap kesim haftası değişikliğini kontrol etmemi ister misiniz?'); return
            if pending=='earlier_email':
                ask('latest_confirm',prefix+' Yalnızca en son kesilen ekstrenizi gönderebilirim. En son ekstrenizi ister misiniz?','En son kesilen ekstrenizi ister misiniz?'); return
            if int(vars.get('send_count',0))>=3: terminal('menu','Sizi ana menüye yönlendiriyorum.'); return
            if not vars.get('statement_date'): terminal('agent_error','Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum.'); return
            address=vars.get('email_tts',vars['email_address'])
            ask('email_confirm',prefix+' Ekstrenizi '+address+' adresine göndermemi ister misiniz?','Ekstrenizi kayıtlı e-posta adresinize göndermemi açıkça onaylıyor musunuz?'); return
        text='Hesap kesim haftası değişikliği için uygunluğunuzu işlem sırasında kontrol edebiliriz.'
        if available: text+=' Ekstrenizi kayıtlı mail adresinize gönderebilirim.'
        ask('offer',prefix+' '+text+' Hangisini istersiniz?','Hesap kesim haftası işlemini'+(' ya da ekstre gönderimini' if available else '')+' ister misiniz?')
    def week_options(prefix=''):
        w=int(vars['current_week']); options=[str(x)+'.' for x in range(1,5) if x!=w]
        ask('week_choice',prefix+' Hesap kesim tarihinizi ayın '+joinnames(options)+' haftasına alabilirim. Hangisini tercih edersiniz?','Hangi hesap kesim haftasını tercih edersiniz?')
    phase=vars.get('phase','start'); ev=str(vars.get('event') or '')
    vars['route']='agent_error'
    if phase=='start':
        vars['seen']='[]'; vars['send_count']=0; vars['changed']='[]'; vars['pending']='none'; vars['figure']='all'; vars['calm_count']=0; vars['read_tries']=0; vars['action_prefix']=''; vars['cards_public']=''; vars['requested_week']=''; vars['select_stage']='name'
        if re.fullmatch('[0-9]{8}',str(vars.get('customerNumber',''))) and vars.get('now'): request('list')
        else: terminal('agent_error','Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum.')
    elif phase.endswith('_wait'):
        service=phase[:-5]; state=vars.get('api_state','failure'); b=obj(vars.get('api_payload'),{})
        if service=='list' and vars.get('api_code')=='FB_IVR_CHANNEL_102': terminal('no_cards','Ekstre borcunu sorgulayabileceğiniz uygun bir kredi kartınız bulunmuyor. Sizi ana menüye aktarıyorum.')
        elif state!='ok':
            if state=='transient' and service not in ['send','change'] and int(vars.get('read_tries',0))<3: request(service)
            else: terminal('agent_week_error' if service in ['week','preview','change'] else 'agent_error','Şu anda hesap kesim tarihinizi değiştiremiyorum, sizi müşteri temsilcimize aktarıyorum.' if service in ['week','preview','change'] else 'Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum.')
        elif service=='list':
            cs=b.get('cards'); cs=cs if isinstance(cs,list) else []
            vars['cards']=json.dumps(cs,ensure_ascii=False); vars['pool']=json.dumps(list(range(len(cs))))
            good=[i for i,c in enumerate(cs) if str(c.get('isMainCard')).lower()!='false' and c.get('status','A')=='A']
            if not good: terminal('no_cards','Ekstre borcunu sorgulayabileceğiniz uygun bir kredi kartınız bulunmuyor. Sizi ana menüye aktarıyorum.')
            elif len(good)==1: choose(good[0])
            else: show_selection()
        elif service=='balance':
            vars['balance']=json.dumps(b,ensure_ascii=False); vars['statement_date']=b.get('statementDate',''); vars['reading']=read_balance(b); after_read()
        elif service=='email':
            address=str(b.get('ibanEmail') or '').strip()
            if norm(b.get('communicationType'))=='phone': address=''
            vars['email_address']=address
            spoken=str(b.get('ttsEmail') or address)
            if len(spoken)>32 or spoken.count('.')>3: spoken=(address[:1]+' ile başlayan '+(address.split('@')[-1] if '@' in address else 'kayıtlı e-posta')+' adresiniz')
            vars['email_tts']=spoken; email_flow()
        elif service=='week':
            vars['week_data']=json.dumps(b,ensure_ascii=False); vars['current_week']=int(b['statementWeek']); vars['current_day']=int(b['statementDay'])
            text=vars.get('action_prefix',''); vars['action_prefix']=''
            text+=' '+intro(selected())+'ın hesap kesim tarihi her ayın '+str(b['statementWeek'])+'. haftası olarak tanımlı. Bir sonraki hesap kesim tarihiniz '+dateword(b.get('nextStatementDate'))+', son ödeme tarihiniz '+dateword(b.get('nextLastPayDate'))+'.'
            if b.get('relationType') in ['M','C']:
                other={'productName':b.get('relatedCardProductName',''),'cardNumberLast4':str(b.get('relatedCardNumber',''))[-4:]}
                text+=' '+intro(other)+'ın hesap kesim haftası da '+str(b['statementWeek'])+'. haftadır. Bir sonraki hesap kesim tarihiniz '+dateword(b.get('nextStatementDate'))+', son ödeme tarihiniz '+dateword(b.get('nextLastPayDate'))+'.'
            chosen=vars.get('requested_week')
            if chosen!='' and chosen is not None:
                w=int(chosen)
                if w==int(b['statementWeek']): terminal('menu',text+' Bu hafta zaten tanımlı, değişiklik gerekmiyor. Sizi ana menüye yönlendiriyorum.')
                elif w in [1,2,3,4]: vars['preview_prefix']=text; vars['read_tries']=0; request('preview')
                else: week_options(text)
            else: ask('week_start',text+' Hesap kesim tarihinizi yılda bir kez değiştirebilirsiniz. Hesap kesim tarihinizi değiştirmek ister misiniz?','Hesap kesim tarihinizi değiştirmek ister misiniz?')
        elif service=='preview':
            vars['preview']=json.dumps(b,ensure_ascii=False); vars['preview_date']=b['statementDate']; vars['preview_due']=b['statementDueDate']; vars['preview_valid']='yes'
            text=vars.get('preview_prefix',''); vars['preview_prefix']=''
            wd=obj(vars.get('week_data'),{})
            if wd.get('relationType') in ['M','C']:
                other=safe_name(wd.get('relatedCardProductName')) or 'sonu '+digits(str(wd.get('relatedCardNumber',''))[-4:])+' ile biten'
                text+=' Bu değişiklik '+('kartınıza bağlı ' if wd['relationType']=='M' else 'kartınızın bağlı olduğu ')+other+' kartınızı da etkileyecek.'
            text+=' Yeni hesap kesim haftanız her ayın '+str(vars['requested_week'])+'. haftası olacak. Yeni hesap kesim tarihiniz '+dateword(b['statementDate'])+', son ödeme tarihiniz '+dateword(b['statementDueDate'])+' olacak. Onaylıyor musunuz?'
            ask('week_confirm',text,'Yeni hafta ve okuduğum tarihleri açıkça onaylıyor musunuz?')
        elif service=='send':
            vars['send_count']=int(vars.get('send_count',0))+1; vars['pending']='none'
            ask('email_done','Ekstreniz kayıtlı e-posta adresinize gönderildi. Sizi ana menüye yönlendiriyorum.','Sizi ana menüye yönlendiriyorum.')
        elif service=='change':
            changed=obj(vars.get('changed'),[]); changed.append(vars['card_number'])
            wd=obj(vars.get('week_data'),{})
            if wd.get('relatedCardNumber'): changed.append(wd['relatedCardNumber'])
            vars['changed']=json.dumps(changed); vars['preview_valid']='no'; vars['pending']='none'
            ask('week_done',intro(selected())+'ın hesap kesim haftası her ayın '+str(vars['requested_week'])+'. haftası olarak değiştirildi. Yeni hesap kesim tarihiniz '+dateword(vars['preview_date'])+', son ödeme tarihiniz '+dateword(vars['preview_due'])+'. Sizi ana menüye yönlendiriyorum.','Sizi ana menüye yönlendiriyorum.')
    else:
        name=str(vars.get('card_name') or '').strip(); dig=re.sub('[^0-9]','',str(vars.get('card_digits') or '')); follow=vars.get('followup','none'); week=vars.get('week_value')
        if follow in ['email','earlier_email','week']: vars['pending']=follow
        if follow in ['due_only','min_only']: vars['figure']=follow
        if week not in ['',None]: vars['requested_week']=week
        if ev=='third_party': terminal('login','Güvenlik nedeniyle yalnızca kendi kartlarınız için yardımcı olabilirim. Kart sahibinin kimlik doğrulaması için sizi giriş adımına aktarıyorum.')
        elif ev=='agent': terminal('agent','Sizi müşteri temsilcimize aktarıyorum.')
        elif ev=='dispute': terminal('agent_dispute','Bu konuda size müşteri temsilcimiz yardımcı olacak, sizi aktarıyorum.')
        elif ev=='pay': terminal('agent_payment','Borç ödeme işleminiz için sizi müşteri temsilcimize aktarıyorum.')
        elif ev=='foreign': terminal('menu_language','Sizi ana menüye aktarıyorum.')
        elif ev=='switch_transaction': terminal('menu','Sizi ana menüye yönlendiriyorum.')
        elif ev=='angry':
            if int(vars.get('calm_count',0))>=3: terminal('agent','Sizi müşteri temsilcimize aktarıyorum.')
            else:
                vars['calm_count']=int(vars.get('calm_count',0))+1
                route('select' if phase=='select' else 'week_choice' if phase=='week_choice' else 'confirm' if phase in ['email_confirm','week_confirm','week_start','latest_confirm'] else 'outside' if phase=='outside' else 'reply','Yaşadığınız güçlüğü anlıyorum. '+vars.get('short_question','Size yardımcı olmak için buradayım.'))
        elif ev=='outside':
            if phase!='outside': vars['resume_phase']=phase; vars['resume_question']=vars.get('short_question','Devam etmek ister misiniz?'); vars['resume_counts']=json.dumps([vars.get('q_tries',0),vars.get('technical_tries',0),vars.get('silences',0)])
            ask('outside','Size bu konuda yardımcı olamıyorum. Sizi ana menüye aktarmamı ister misiniz?','Sizi ana menüye aktarmamı ister misiniz?')
        elif ev=='silence':
            vars['silences']=int(vars.get('silences',0))+1
            if int(vars['silences'])>=3: terminal('silence_end','Sesinizi alamadığım için görüşmeyi sonlandırıyorum.')
            else: route('select' if phase=='select' else 'week_choice' if phase=='week_choice' else 'confirm' if phase in ['email_confirm','week_confirm','week_start','latest_confirm'] else 'outside' if phase=='outside' else 'reply',vars.get('short_question','Yanıtınızı alabilir miyim?'))
